using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEditor;using UnityEngine;using UnityEngine.Playables;using UnityEngine.Animations;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Sandbox.CharacterSystem;
public static class RenderFittedPoses {
 static Mesh Snapshot(SkinnedMeshRenderer r,Transform root){if(r.name=="BAKED_Outfits_LOD0"){var binding=root.GetComponent<CharacterGarmentSurfaceBinding>();if(binding){binding.ApplyPose();return UnityEngine.Object.Instantiate(binding.OutputMesh);}}var mesh=UnityEngine.Object.Instantiate(r.sharedMesh);var vertices=mesh.vertices;var matrices=r.bones.Select((b,j)=>root.worldToLocalMatrix*b.localToWorldMatrix*mesh.bindposes[j]).ToArray();var output=new Vector3[vertices.Length];int limit=r.quality==SkinQuality.Auto?(int)QualitySettings.skinWeights:(int)r.quality;using(var counts=mesh.GetBonesPerVertex())using(var weights=mesh.GetAllBoneWeights()){int at=0;for(int i=0;i<vertices.Length;i++){float sum=0;for(int k=0;k<counts[i];k++){var w=weights[at++];if(k>=limit)continue;output[i]+=matrices[w.boneIndex].MultiplyPoint3x4(vertices[i])*w.weight;sum+=w.weight;}if(sum>0)output[i]/=sum;}}mesh.ClearBlendShapes();mesh.vertices=output;mesh.RecalculateNormals();mesh.RecalculateBounds();return mesh;}
 public static object Run(){if(EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Edit Mode required");var root=PrefabUtility.LoadPrefabContents("Assets/_Sandbox/Characters/Ethan_V2/Ethan_V2.prefab");var scene=root.scene;var resources=new List<UnityEngine.Object>();try{
 var renderers=root.GetComponentsInChildren<SkinnedMeshRenderer>(true).Where(r=>r.name=="BAKED_body_lod0_mesh"||r.name=="BAKED_Outfits_LOD0"||r.name=="BAKED_head_lod0_mesh").ToArray();foreach(var r in root.GetComponentsInChildren<Renderer>(true))r.enabled=false;
 var shader=Shader.Find("Universal Render Pipeline/Unlit");var skin=new Material(shader);skin.SetColor("_BaseColor",new Color(.65f,.43f,.3f));var shirt=new Material(shader);shirt.SetColor("_BaseColor",new Color(.15f,.19f,.23f));shirt.SetFloat("_Cull",0);resources.Add(skin);resources.Add(shirt);var head=new Material(shader);head.SetColor("_BaseColor",new Color(.65f,.43f,.3f));resources.Add(head);
 var camObject=new GameObject("Fit check camera");SceneManager.MoveGameObjectToScene(camObject,scene);resources.Add(camObject);var camera=camObject.AddComponent<Camera>();camera.scene=scene;camera.cullingMask=1<<30;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.8f,.8f,.8f);camera.orthographic=true;camera.orthographicSize=.6f;camera.transform.position=new Vector3(0,1.25f,3);camera.transform.LookAt(new Vector3(0,1.25f,0));
 var defs=AssetDatabase.FindAssets("t:AnimationDefinition",new[]{"Assets/_Sandbox"}).Select(AssetDatabase.GUIDToAssetPath).Select(AssetDatabase.LoadAssetAtPath<AnimationDefinition>).Where(d=>d&&d.Clip&&d.Clip.isHumanMotion&&(d.name=="Idle"||d.name=="Thinking"||d.name=="Waving")).ToArray();var animator=root.GetComponentInChildren<AnimationModule>(true).Animator;var bridge=root.GetComponent<CharacterSkeletonPoseBridge>();Directory.CreateDirectory("Data/EthanV2/ClothingRepair/FittedRenders");var results=new List<object>();
 foreach(var d in defs){var graph=PlayableGraph.Create("Rendered mesh fit sample");try{graph.SetTimeUpdateMode(DirectorUpdateMode.Manual);var p=AnimationClipPlayable.Create(graph,d.Clip);p.SetApplyFootIK(false);var output=AnimationPlayableOutput.Create(graph,"pose",animator);output.SetSourcePlayable(p);graph.Play();p.SetTime(d.Clip.length*.5);graph.Evaluate(0);bridge.ApplyPose();var temporary=new List<UnityEngine.Object>();try{foreach(var r in renderers){var mesh=Snapshot(r,root.transform);var go=new GameObject("Posed surface");SceneManager.MoveGameObjectToScene(go,scene);go.layer=30;go.AddComponent<MeshFilter>().sharedMesh=mesh;var renderer=go.AddComponent<MeshRenderer>();renderer.sharedMaterials=Enumerable.Repeat(r.name=="BAKED_Outfits_LOD0"?shirt:r.name=="BAKED_head_lod0_mesh"?head:skin,mesh.subMeshCount).ToArray();temporary.Add(go);temporary.Add(mesh);}
 foreach(string side in new[]{"front","back"}){camera.transform.position=new Vector3(0,1.25f,side=="front"?3:-3);camera.transform.LookAt(new Vector3(0,1.25f,0));var rt=RenderTexture.GetTemporary(700,900,24);try{camera.targetTexture=rt;camera.Render();var previous=RenderTexture.active;RenderTexture.active=rt;var texture=new Texture2D(700,900,TextureFormat.RGB24,false);texture.ReadPixels(new Rect(0,0,700,900),0,0);texture.Apply();RenderTexture.active=previous;File.WriteAllBytes("Data/EthanV2/ClothingRepair/FittedRenders/"+d.name+"_"+side+".png",texture.EncodeToPNG());UnityEngine.Object.DestroyImmediate(texture);}finally{camera.targetTexture=null;RenderTexture.ReleaseTemporary(rt);}}results.Add(new{pose=d.name});}finally{foreach(var item in temporary)UnityEngine.Object.DestroyImmediate(item);}}finally{graph.Destroy();}}
 return results;
 }finally{foreach(var item in resources)if(item)UnityEngine.Object.DestroyImmediate(item);PrefabUtility.UnloadPrefabContents(root);}}
}
